/*
 * A301848  Number of states generated by morphism during inflation stage of
 *          paper-folding sequence.
 * https://oeis.org/A301848
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 100, u16 n <= 100, u32 n <= 100, u64 n <= 100,
 *            u128 n <= 100, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A301848: Number of states generated by the morphism
 *   1 → 1 3
 *   2 → 2 3
 *   3 → 1 4
 *   4 → 2 4
 * starting from state 1.
 * Algorithm: for an index n (0‑based) traverse the binary expansion of n
 * from the most significant bit to the least; a bit 0 selects the left
 * child (first symbol of the expansion), a bit 1 selects the right child
 * (second symbol).  The state reached is a(n). */

#include <stdint.h>
#include <stdbool.h>

seq_t a(idx_t n)
{
    /* Left (first symbol) and right (second symbol) children for each state. */
    static const uint8_t left_child[5]  = {0, 1, 2, 1, 2};
    static const uint8_t right_child[5] = {0, 3, 3, 4, 4};

    /* Find the position of the most significant bit of n. */
    idx_t temp = n, msb = 0;
    while (temp > 1) {
        temp >>= 1;
        msb++;
    }

    /* Traverse from the root state 1 following the bits of n. */
    uint8_t state = 1;
    for (idx_t i = msb; ; --i) {
        uint8_t bit = (n >> i) & 1U;
        state = bit ? right_child[state] : left_child[state];
        if (i == 0)
            break;
    }

    return (seq_t)state;
}
